python - <<'PY'
import re,json
text=open('fit1.txt').read().splitlines()
cf={}
gaps=[]
obs={}
for line in text:
    m=re.match(r'\s*(\d+)\s+([-0-9.]+)\s+([-0-9.]+)\s+([-0-9.]+)', line)
    if m:
        t=int(m.group(1)); o=float(m.group(2)); s=float(m.group(3)); g=float(m.group(4))
        if 41<=t<=60:
            cf[str(t)]=s; gaps.append(g); obs[str(t)]=o
att=sum(gaps)/len(gaps)
ans={
 "counterfactual": cf,
 "att": att,
 "rationale": "I used all 29 never-treated donors and the full pre-treatment period 1-40. The predictor set includes Z1 and Z2, which are time-invariant covariates, plus the treated outcome in each pre-treatment period as special predictors, so the donor weights are chosen to closely reproduce the pre-treatment outcome path as well as the covariates. V was selected by Synth to minimize pre-treatment outcome MSPE over periods 1-40; compared with a coarser five-period-block outcome specification, this all-period outcome specification gave the lower pre-treatment MSPE, so I used it for the submitted counterfactuals."
}
open('answer.json','w').write(json.dumps(ans,indent=2))
print(json.dumps(ans,indent=2))
PY
cat answer.json
